/**
 * Reference output of inkvec 0.2.7 (`fit_pixels` → every candidate, flat first, and the
 * index `select` picks, that one in full) for the scenes of `scenes.ts` and for crops of gradient regions of
 * three corpus images (synthetic gradient_linear and gradient_radial, noto-emoji u1f36a and
 * u1f351 at 128 px, labeled by inkvec's own band merge). Points are inkvec's, pixel centers
 * at integer indices: Trazor's are these plus ½. A candidate is
 * `[kind, interp, geometry, c0, c1, mids, chi2, params, cost]`, geometry `[x0, y0, x1, y1, 0, 0]`
 * for a linear ramp and `[cx, cy, r, aspect, angle, 0]` for a radial one, a mid stop
 * `[offset, r, g, b]`.
 */

/** One inkvec candidate in full. */
export type RefCandidate = [
  string,
  string,
  number[],
  number[],
  number[],
  number[][],
  number,
  number,
  number,
]

/** One inkvec candidate in brief: `[kind, interp, mid stops, chi2, cost]`. */
export type RefBrief = [string, string, number, number, number]

/** inkvec's candidates for one region of a scene. */
export interface SceneRef {
  scene: string
  evidence: 0 | 1
  label: number
  selected: number
  best: RefCandidate
  candidates: RefBrief[]
}

/** A crop of a corpus image: label 1 is the region (and 2 a second one for a union), 0 the rest. */
export interface CorpusRef {
  name: string
  w: number
  h: number
  sigma: number
  lambda: number
  /**
   * The colors of the labeled pixels (label ≠ 0) in raster order, over white: 8-bit
   * levels (`rgb8`, level/255 in single precision) or single-precision bits
   * (`rgb32`), deflated and base64. Unlabeled pixels are not read by the fits
   * (white).
   */
  rgb8?: string
  rgb32?: string
  /** Run-length labels, `label*count` comma-separated. */
  labels: string
  selected: number
  best: RefCandidate
  candidates: RefBrief[]
  /** For a union crop: inkvec's fits of region 1, region 2 and their union, and the common-pixel gain. */
  union?: { left: RefCandidate; right: RefCandidate; union: RefCandidate; gain: number }
}

